fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length,
    // we can iterate over them simultaneously using zip,
    // comparing each pair and collecting the results into a Vec<bool>.
    
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x >= y)
        .collect()
}